            "wenxin": "文心一言"
        };
    },

    "getVoices": function(category) {
        var mm = {};

        if (category === "all") {
            var voiceList = voiceListCache || downloadVoiceList();
            if (voiceList) {
                for (var i = 0; i < voiceList.length; i++) {
                    var v = voiceList[i];
                    mm[v.voice_id] = {
                        name: v.name,
                        gender: v.gender,
                        icon: v.icon_url
                    };
                }
            }

            var qianwenList = qianwenVoiceCache || downloadQianwenVoiceList();
            if (qianwenList) {
                for (var i = 0; i < qianwenList.length; i++) {
                    var v = qianwenList[i];
                    mm[v.voice_id] = {
                        name: v.voice_name,
                        gender: v.gender,
                        icon: v.icon
                    };
                }
            }

            var wenxinList = wenxinVoiceCache || downloadWenxinVoiceList();
            if (wenxinList) {
                for (var i = 0; i < wenxinList.length; i++) {
                    var v = wenxinList[i];
                    mm[v.id] = {
                        name: v.name,
                        gender: v.gender,
                        icon: v.icon
                    };
                }
            }

            return mm;
        }

        if (category === "qianwen") {
            var list = qianwenVoiceCache || downloadQianwenVoiceList();
            if (list) {
                for (var i = 0; i < list.length; i++) {
                    var v = list[i];
                    mm[v.voice_id] = {
                        name: v.voice_name,
                        gender: v.gender,
                        icon: v.icon
                    };
                }
            }
            return mm;
        }

        if (category === "wenxin") {
            var list = wenxinVoiceCache || downloadWenxinVoiceList();
            if (list) {
                for (var i = 0; i < list.length; i++) {
                    var v = list[i];
                    mm[v.id] = {
                        name: v.name,
                        gender: v.gender,
                        icon: v.icon
                    };
                }
            }
            return mm;
        }

        var voiceList = voiceListCache || downloadVoiceList();
        if (!voiceList) return mm;

        for (var i = 0; i < voiceList.length; i++) {
            var v = voiceList[i];
            var match = false;

            if (category === "pro" && v.is_pro) {
                match = true;
            } else if (category === "emotion" && v.is_emotion) {
                match = true;
            } else if (category === "female" && v.gender === "女性") {
                match = true;
            } else if (category === "male" && v.gender === "男性") {
                match = true;
            } else if (category === "singing" && v.is_singing) {
                match = true;
            }

            if (match) {
                mm[v.voice_id] = {
                    name: v.name,
                    gender: v.gender,
                    icon: v.icon_url
                };
            }
        }
        return mm;
    },

