function handleTextMessage(msg) {
    try {
        var data = JSON.parse(msg);
        var event = data.event || "";
        if (event === "TaskStarted") {
            sendText(req.text);
            var t = new java.lang.Thread(new java.lang.Runnable({
                run: function() {
