                    } catch(e) {}
                }
            }));
            t.start();
        } else if (event === "TTSSentenceStart") {
        } else if (event === "TTSSentenceEnd") {
        } else if (event === "TaskFinished") {
            flushAudio("Done");
        } else if (data.status_code && data.status_code !== 20000000) {
            try { callback.error("API错误: " + (data.status_text || JSON.stringify(data))); } catch(e) {}
        }
    } catch(e) {}
}

function handleBinaryData(buf) {
    try {
        if (!buf) return;

        var javaBytes = null;

        if (typeof buf.getClass === 'function' && buf.getClass().isArray()) {
            javaBytes = buf;
        }
        else if (typeof buf === 'object' && typeof buf.toString === 'function') {
            try {
                var base64Str = buf.toString('base64');
                javaBytes = android.util.Base64.decode(base64Str, 0);
            } catch(e) {
                if (typeof buf.length === 'number' && buf.length > 0) {
                    var len = buf.length;
                    var baos = new java.io.ByteArrayOutputStream(len);
                    for (var i = 0; i < len; i++) {
                        baos.write(buf[i] & 0xFF);
                    }
                    javaBytes = baos.toByteArray();
                }
            }
        }
        else if (typeof buf === 'object' && typeof buf.length === 'number' && buf.length > 0) {
            var len = buf.length;
            var baos = new java.io.ByteArrayOutputStream(len);
            for (var i = 0; i < len; i++) {
                baos.write(buf[i] & 0xFF);
            }
            javaBytes = baos.toByteArray();
        }
        else if (typeof buf === 'string') {
            try {
                javaBytes = android.util.Base64.decode(buf, 0);
            } catch(e) {}
        }

        if (javaBytes && javaBytes.length > 0) {
            audioChunks.push(javaBytes);
            audioLength += javaBytes.length;
        }
    } catch(e) {}
}

function startTimeoutCheck() {
    var requestId = currentRequestId;
    var t = new java.lang.Thread(new java.lang.Runnable({
        run: function() {
            try {
                java.lang.Thread.sleep(CONFIG.timeoutMs);
                if (!isFinished && ws !== null && requestId === currentRequestId) {
                    try { ws.cancel(); } catch(e) {}
                    ws = null;
                    isWsReady = false;
                    isRequesting = false;
                    if (audioChunks.length > 0) {
                        flushAudio("Timeout");
                    } else {
                        try { callback.error("请求超时，请检查网络或配置"); } catch(e) {}
                        try { callback.close(); } catch(e) {}
                    }
                }
            } catch(e) {}
        }
    }));
    t.start();
}

function flushAudio(reason) {
    if (isFinished) return;
    isFinished = true;
    try {
        if (audioChunks.length === 0) {
            try { callback.error("无音频数据 (" + reason + ")"); } catch(e) {}
            try { callback.close(); } catch(e) {}
            return;
        }

        var audioFormat = req.format || "mp3";
        var sampleRate = req.sampleRate || CONFIG.sampleRate;

        if (audioFormat === "mp3") {
            // MP3 格式：直接输出，不需要 WAV 头
            var totalLen = audioLength;
            var stream = new java.io.ByteArrayOutputStream(totalLen);
            for (var j = 0; j < audioChunks.length; j++) {
                var chunk = audioChunks[j];
                if (chunk && chunk.length > 0) {
                    stream.write(chunk);
                }
            }
            var finalBytes = stream.toByteArray();
            callback.write(finalBytes);
            stream.close();
        } else {
            // PCM 格式：添加 WAV 头
            var silenceBytes = sampleRate * 2 * CONFIG.silenceMs / 1000;
            var totalLen = silenceBytes + audioLength + silenceBytes;
            var stream = new java.io.ByteArrayOutputStream();
            writeWavHeader(stream, totalLen, sampleRate);
            var silenceArray = getSilenceBytes(silenceBytes);
            if (silenceArray) {
                stream.write(silenceArray);
            }
            for (var j = 0; j < audioChunks.length; j++) {
                var chunk = audioChunks[j];
                if (chunk && chunk.length > 0) {
                    stream.write(chunk);
                }
            }
            if (silenceArray) {
                stream.write(silenceArray);
            }
            var finalBytes = stream.toByteArray();
            callback.write(finalBytes);
            stream.close();
        }
    } catch(e) {
        try { callback.error("音频处理错误: " + e.message); } catch(e2) {}
    }
    try { callback.close(); } catch(e) {}
    isRequesting = false;
}

