    var fallback = {
        "excited": ["happy"],
        "depressed": ["sad"],
        "comfort": ["tender", "sad", "neutral"],
        "coldness": ["neutral"],
        "hate": ["angry"],
        "tension": ["fear", "surprised", "neutral"],
