        "surprised": ["fear", "happy", "neutral"],
        "advertising": ["news", "neutral"],
        "entertainment": ["happy", "neutral"],
        "news": ["neutral"]
    };
    var candidates = fallback[emotionName] || [];
    for (var j = 0; j < candidates.length; j++) {
        for (var k = 0; k < list.length; k++) {
