var PluginJS = {
    "name": "豆包321",
    "id": "doubao.official.latest.nologin.emobridge.jtts.20260817",
    "author": "豆包 APK 官方321音色 / 猫剪免登录合成核心 / JTTS",
    "version": 1,
    "vars": {},
    "iconUrl": "https://www.helloimg.com/i/2026/03/26/69c47d2e087de.jpg",

    "onStop": function() {
        if (timeoutHandler !== null) {
            timeoutHandler.interrupt();
            timeoutHandler = null;
        }
        if (ws !== null) {
            try { ws.cancel(); } catch(e) {}
            ws = null;
        }
        isRequesting = false;
        isWsReady = false;
        lastVoiceId = "";
    },

    "getAudioV2": function(request, callback2) {
        try {
            if (isRequesting) {
                callback2.error("请等待当前请求完成");
                try { callback2.close(); } catch(e) {}
                return;
            }
            var now = Date.now();
            if (now - lastRequestTime < 200) {
                callback2.error("请求过快，请稍后再试");
                try { callback2.close(); } catch(e) {}
                return;
            }
            isRequesting = true;
            lastRequestTime = now;
            currentRequestId++;

            var voiceId = String(request.voice || "").trim();
            if (!voiceId) {
                voiceId = "zh_female_vv_uranus_bigtts";
            }
            voiceId = resolveAvailableMaoxiangVoiceId(voiceId);

            var isClone = isCloneVoice(voiceId);

            if (ws !== null) {
                try { ws.cancel(); } catch(e) {}
                ws = null;
            }
            isWsReady = false;

            // v14：本插件只走猫剪/豆包免登录通道，不再每次请求前探测通义/文心远程音色表，避免无关网络阻塞。
            if (isClone) {
                callback2.error("当前免登录通道不支持 create_voice_ 克隆音色");
                try { callback2.close(); } catch(e) {}
                isRequesting = false;
                return;
            }

            handleMaoxiangRequest(request, callback2, voiceId);

        } catch(e) {
            isRequesting = false;
            try { callback2.error("插件异常: " + e.message); } catch(e2) {}
            try { callback2.close(); } catch(e2) {}
        }
    },

    "lastTestText": "你好，今天天气不错，我很开心！"
};

// getAudioV2 记录测试文本
(function() {
    var original = PluginJS.getAudioV2;
    PluginJS.getAudioV2 = function(request, callback2) {
