            if (response.code() !== 200) {
                throw "获取声音列表失败: HTTP-" + response.code();
            }

            let textData = response.body().string();
            voiceData = parseVoiceData(textData);
            ttsrv.writeTxtFile(CACHE_FILE, JSON.stringify(voiceData));
        }

        currentVoices['zh'] = voiceData;
    }
};

// 修复原代码正则错误 \s 多余转义
function parseVoiceData(textData) {
    let result = {};

    textData = textData.replaceAll("\r\n", "\n").replaceAll("\r", "\n");
    let lines = textData.split("\n");

    for (let line of lines) {
        if (!line.trim()) continue;

        let separatorIndex = line.indexOf('. ');
        if (separatorIndex === -1) continue;

        let id = line.substring(0, separatorIndex).trim();
        id = id.replaceAll(/\s/g, "");
        id = id.replaceAll(/\D/g, "");

        let name = line.substring(separatorIndex + 2).trim();
        name = name.replaceAll("[\r\n]", "");

        if (id && name) {
            result[id] = name;
        }
    }

    return result;
}

