                return outputStream.toByteArray();

            } else {
                let response = ttsrv.httpGet(url);
                if (!response || response.code() !== 200) {
                    throw new Error('HTTP请求失败: ' + (response ? response.code() : 'no response'));
                }
                let audioData = response.body().bytes();
                if (onAudioData && typeof onAudioData === 'function') {
                    onAudioData(audioData, audioData.length);
                }
