let EditorJS = {
    'playAudioStream': function(texts, locale, voice, speed, volume, pitch) {
        if (!texts || texts.length === 0) return;
        let combinedText = this.combineTextIntelligently(texts);
        try {
            PluginJS.getAudioStream(combinedText, locale, voice, speed, volume, pitch, 
                function(audioChunk, chunkSize) {
                    if (audioChunk && chunkSize > 0) {
                        ttsrv.playAudioChunk(audioChunk);
                    }
                }
            );
        } catch (error) {
            console.error('流式播放失败: ', error);
            let fullText = texts.join('');
            let audioData = PluginJS.getAudio(fullText, locale, voice, speed, volume, pitch);
            ttsrv.playAudio(audioData);
        }
    },

    'combineTextIntelligently': function(texts) {
        if (!texts || texts.length === 0) return '';
        if (texts.length === 1) return texts[0];

        let result = '';
        let currentChunk = '';
        let MAX_CHUNK_LEN = 150;
        let BREAK_WORDS = ['或者', '还是', '而且', '但是', '不过', '所以', '然而', '虽然'];

        for (let i = 0; i < texts.length; i++) {
            let text = texts[i].trim();
            if (!text) continue;
            let isBreakWord = false;
            for(let j=0; j<BREAK_WORDS.length; j++) {
                if(text.indexOf(BREAK_WORDS[j]) === 0) {
                    isBreakWord = true;
                    break;
                }
            }
            if (isBreakWord) {
                if (currentChunk) {
                    result += currentChunk;
                    currentChunk = '';
                }
                currentChunk += text;
                continue;
            }
            if (currentChunk.length + text.length < MAX_CHUNK_LEN) {
                currentChunk += text;
            } else {
                result += currentChunk;
                currentChunk = text;
            }
            if (/[。！？；]$/.test(text) && currentChunk.length > 50) {
                result += currentChunk;
                currentChunk = '';
            }
        }
        if (currentChunk) {
            result += currentChunk;
        }
        return result;
    },

    'getAudioSampleRate': function(locale, voice) {
        return 24000;
    },

    'onLoadData': function() {
    },

    'getLocales': function() {
        return ['zh-CN'];
    },

    '_officialVoiceCache': null,
    '_officialVoiceCacheAt': 0,
    '_officialVoiceCacheTtlMs': 10 * 60 * 1000,

    '_xfUuid': function(len, radix) {
        let chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'.split('');
        let result = [];
        radix = radix || chars.length;
        for (let i = 0; i < len; i++) {
            result[i] = chars[0 | (Math.random() * radix)];
        }
        return result.join('');
    },

    '_xfSignValue': function(value) {
        let type = Object.prototype.toString.call(value);
        if (type === '[object Object]') {
            let keys = Object.keys(value).sort();
            let parts = [];
            for (let i = 0; i < keys.length; i++) {
                let key = keys[i];
                let signed = this._xfSignValue(value[key]);
                if (signed || Object.prototype.toString.call(value[key]) === '[object Array]') {
                    parts.push(key + '=' + signed);
                }
            }
            return parts.join('&');
        }
        if (type === '[object Array]') {
            let arr = [];
            for (let i = 0; i < value.length; i++) {
                arr.push(this._xfSignValue(value[i]));
            }
            return arr.join(',');
        }
        if (value === null) return 'null';
        if (typeof value === 'undefined') return '';
        return String(value);
    },

    '_xfMd5': function(text) {
        return String(ttsrv.md5Encode(String(text || '')) || '').toLowerCase();
    },

    '_xfSortedObject': function(obj) {
        let sorted = {};
        if (!obj) return sorted;
        let keys = Object.keys(obj).sort();
        for (let i = 0; i < keys.length; i++) {
            sorted[keys[i]] = obj[keys[i]];
        }
        return sorted;
    },

    '_xfPostVideoApi': function(path, param) {
        param = this._xfSortedObject(param || {});
        let base = {
            'appid': 'xfpy',
            'sid': this._xfUuid(32, 50),
            'channelId': '40000001',
            'userId': '',
            'osid': 0
        };
        let body = {
            'param': param,
            'base': base
        };
        let baseSign = this._xfMd5(this._xfSignValue(base));
        let sign = this._xfMd5(this._xfSignValue(body) + baseSign);
        let headers = {
            'content-type': 'application/json;charset=UTF-8',
            'User-Agent': PluginJS.CONST.UA,
            'Referer': 'https://peiyin.xunfei.cn/make',
            'Origin': 'https://peiyin.xunfei.cn',
            'Accept': 'application/json, text/plain, */*',
            'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
            'x-accept-language': 'zh_CN',
            'authorization': '',
            'X-Channel-No': '40000001',
            'sign': sign
        };
        let resp = ttsrv.httpPost('https://peiyin.xunfei.cn' + path, JSON.stringify(body), headers);
        if (!resp || resp.code() !== 200) {
            throw new Error('讯飞官网音色列表请求失败: ' + (resp ? resp.code() : 'no response'));
        }
        let respStr = ttsrv.bytesToStr(resp.body().bytes());
        let json = JSON.parse(respStr);
        if (json.code !== 0 && json.code !== 200) {
            throw new Error('讯飞官网音色列表返回异常: ' + (json.desc || json.message || json.code));
        }
        return json.data || {};
    },

    '_xfGenderName': function(value) {
        value = String(value || '');
        if (value === '1' || value === '男') return '男';
        if (value === '2' || value === '女') return '女';
        return '';
    },

    '_xfIsChineseVoice': function(speaker, common) {
        let text = [
            speaker && speaker.speakerName,
            speaker && speaker.emotDesc,
            common && common.speakerName,
            common && common.speakerLanguage,
            common && common.speakerStyle,
            common && common.speakerSpecialty,
            common && common.tag
        ].join('|');
        let foreign = ['英语', '法语', '西班牙语', '日语', '韩语', '德语', '阿拉伯语', '泰语', '俄语', '马来语', '印尼语', '意大利语', '菲律宾语', '葡萄牙语', '越南语', '波兰语', '匈牙利语'];
        for (let i = 0; i < foreign.length; i++) {
            if (text.indexOf(foreign[i]) >= 0) return false;
        }
        return /[\u4e00-\u9fa5]/.test(text);
    },

    '_xfVoiceLabel': function(speaker, common) {
        let name = String((speaker && speaker.speakerName) || (common && common.speakerName) || '').trim();
        let emot = String((speaker && speaker.emotDesc) || '').trim();
        let gender = this._xfGenderName(common && common.speakerGender);
        let style = String((common && common.speakerStyle) || '').trim();
        let specialty = String((common && common.speakerSpecialty) || '').trim();
        let language = String((common && common.speakerLanguage) || '').trim();
        let tag = String((common && common.tag) || '').replace(/\|/g, '/').trim();
        let parts = [];
        if (name) parts.push(name);
        if (emot && name.indexOf(emot) < 0) parts.push(emot);
        if (gender) parts.push(gender);
        if (style) parts.push(style);
        let tail = [];
        if (specialty) tail.push(specialty);
        if (language) tail.push(language);
        if (tag) tail.push(tag);
        if (tail.length > 0) parts.push(tail.join('/'));
        return parts.join('｜') || String(speaker && speaker.speakerNo || '');
    },

    '_readOfficialVoices': function(forceRefresh) {
        let now = new Date().getTime();
        if (!forceRefresh && this._officialVoiceCache && (now - this._officialVoiceCacheAt) < this._officialVoiceCacheTtlMs) {
            return this._officialVoiceCache;
        }
        let commonData = this._xfPostVideoApi('/video-api/asset/qry_common_speakers', {
            'pageIndex': 1,
            'pageSize': 999,
            'needCount': 1
        });
        let speakerData = this._xfPostVideoApi('/video-api/asset/qry_all_speaker_simple', {});
        let commonList = commonData.commonSpeakers || [];
        let commonMap = {};
        for (let i = 0; i < commonList.length; i++) {
            let common = commonList[i];
            if (common && typeof common.commonId !== 'undefined') {
                commonMap[String(common.commonId)] = common;
            }
        }
        let speakerMap = speakerData.speakerSimpleMap || {};
        let voices = {
            'custom': '自定义声音'
        };
        let keys = Object.keys(speakerMap);
        for (let i = 0; i < keys.length; i++) {
            let key = keys[i];
            let speaker = speakerMap[key];
            if (!speaker || String(speaker.isValid) === '0') continue;
            let voiceId = String(speaker.speakerNo || key || '').trim();
            if (!voiceId) continue;
            let common = commonMap[String(speaker.commonId || '')] || null;
            if (!this._xfIsChineseVoice(speaker, common)) continue;
            voices[voiceId] = this._xfVoiceLabel(speaker, common);
        }
        if (Object.keys(voices).length <= 20) {
            throw new Error('讯飞官网音色列表数量异常: ' + Object.keys(voices).length);
        }
        this._officialVoiceCache = voices;
        this._officialVoiceCacheAt = now;
        console.log('讯飞官网实时音色列表加载完成: ' + Object.keys(voices).length);
        return voices;
    },

