  if (uiContext === null) return;
  try {
    android.os.Handler(android.os.Looper.getMainLooper()).post(new java.lang.Runnable({
      run: function() {
        android.widget.Toast.makeText(uiContext, message, android.widget.Toast.LENGTH_SHORT).show();
