// 获取当前书籍名（使用 ttsrv.httpGet 替代 Jsoup）
function getCurrentBookName() {
  try {
    var resp = ttsrv.httpGet("http://localhost:1122/getBookshelf");
    if (resp.code() === 200) {
      var body = resp.body().string();
      var data = JSON.parse(body);
      if (data.isSuccess && data.data && data.data.length > 0) {
        var book = data.data[0];
        return book.name || book.bookName || "";
      }
    }
  } catch(e) { safeLog("获取当前书籍名异常: " + e.message); }
  return "";
}

function isSoundEffectAllowed(soundName) {
  var kaiqiList = loadKaiqiList();
  if (kaiqiList.indexOf(soundName) === -1) return true;
  var currentBook = getCurrentBookName();
  if (!currentBook) return false;
  var enabled = loadEnabledBooks();
  return enabled.indexOf(currentBook) !== -1;
}

// 处理音效请求
function processAudioWithCache(voiceName) {
  try {
    if (!isSoundEffectAllowed(voiceName)) {
      safeLog("音效 '" + voiceName + "' 未在当前书籍启用，使用兜底");
      return getFallbackAudioStream();
    }
    var cached = getAudioFromCacheAndRotate(voiceName);
    if (cached) return cached;
    var collected = collectAudioVariants(voiceName);
    if (collected.length > 0) {
      saveAudioArrayToCache(collected, voiceName, 0);
      var bytes = android.util.Base64.decode(collected[0], android.util.Base64.DEFAULT);
      return new java.io.ByteArrayInputStream(bytes);
    }
    return getFallbackAudioStream();
  } catch(e) {
    safeLog("processAudioWithCache 异常: " + e.message);
    return getFallbackAudioStream();
  }
}

function processCustomAudio(customName, customUrl) {
  try {
    if (!isSoundEffectAllowed(customName)) {
      safeLog("自定义音效 '" + customName + "' 未启用，使用兜底");
      return getFallbackAudioStream();
    }
    var cached = getAudioFromCacheAndRotate(customName);
    if (cached) return cached;
    var collected = [];
    if (customUrl && isValidUrl(customUrl)) {
      var base = downloadCustomUrlAudio(customUrl);
      if (base) collected.push(base);
    }
    var others = collectAudioVariants(customName);
    for (var i = 0; i < others.length; i++) collected.push(others[i]);
    if (collected.length > 0) {
      saveAudioArrayToCache(collected, customName, 0);
      var bytes = android.util.Base64.decode(collected[0], android.util.Base64.DEFAULT);
      return new java.io.ByteArrayInputStream(bytes);
    }
    return getFallbackAudioStream();
  } catch(e) {
    safeLog("processCustomAudio 异常: " + e.message);
    return getFallbackAudioStream();
  }
}

// 提取中文
function extractChineseChars(text) {
  if (!text || typeof text !== 'string') return null;
  var clean = text.trim().replace(/^\(|\)$/g, '');
  var match = clean.match(/[\u4e00-\u9fa5]+/g);
  return match ? match.join('') : null;
}

// ================== 全局 JSON 处理（异步子线程）==================
function downloadGlobalMp3JsonAsync(showStartToast) {
  var thread = new java.lang.Thread(new java.lang.Runnable({
    run: function() {
      safeLog("【全局JSON】子线程开始下载：" + GLOBAL_MP3_JSON_URL);
      try {
        var resp = ttsrv.httpGet(GLOBAL_MP3_JSON_URL);
        if (resp.code() === 200) {
          var input = resp.body().byteStream();
          var baos = new java.io.ByteArrayOutputStream();
          var b;
          while ((b = input.read()) !== -1) baos.write(b);
          var jsonStr = baos.toString("UTF-8");
          baos.close();
          input.close();
          var test = JSON.parse(jsonStr);
          if (test && typeof test === 'object') {
            writeTextFile("mp3_base64.json", jsonStr);
            safeLog("全局MP3库下载成功");
            showToast("全局音效库下载完成");
          } else {
            safeLog("全局MP3库下载内容无效");
            showToast("全局音效库下载失败：无效JSON");
          }
        } else {
          safeLog("全局MP3库下载失败，状态码：" + resp.code());
          showToast("全局音效库下载失败，HTTP " + resp.code());
        }
      } catch(e) {
        safeLog("全局MP3下载异常: " + e.message);
        showToast("全局音效库下载异常：" + e.message);
      }
    }
  }));
  if (showStartToast) {
    showToast("正在缓存全部音效…");
  }
  thread.start();
}

function reloadGlobalMp3Json() {
  deleteFile("mp3_base64.json");
  showToast("正在重新缓存全部音效...");
  downloadGlobalMp3JsonAsync(false);
}

function loadGlobalMp3Json() {
  if (globalJsonData !== null) return globalJsonData;
  try {
    if (!fileExists("mp3_base64.json")) return null;
    globalJsonData = JSON.parse(readTextFile("mp3_base64.json"));
    return globalJsonData;
  } catch(e) { return null; }
}

// ================== 书籍选择对话框（已移除50本限制） ==================
function showBookSelectionDialog(ctx, selectAll) {
  var thread = new java.lang.Thread(new java.lang.Runnable({
    run: function() {
      try {
        var resp = ttsrv.httpGet("http://localhost:1122/getBookshelf");
        if (resp.code() !== 200) {
          showToast("获取书籍列表失败，状态码：" + resp.code());
          return;
        }
        var body = resp.body().string();
        var data = JSON.parse(body);
        if (!data.isSuccess || !data.data || data.data.length === 0) {
          showToast("书架无书籍");
          return;
        }
        var books = data.data;
        var bookNames = [];
        for (var i = 0; i < books.length; i++) {
          var name = books[i].name || books[i].bookName;
          if (name) bookNames.push(name);
        }
        // 注意：此处不再限制数量，显示全部书籍

        var enabled = loadEnabledBooks();
        var checked = [];
        for (var j = 0; j < bookNames.length; j++) {
          checked[j] = selectAll ? true : (enabled.indexOf(bookNames[j]) !== -1);
        }
        // 主线程显示对话框
        android.os.Handler(android.os.Looper.getMainLooper()).post(new java.lang.Runnable({
          run: function() {
            var builder = new android.app.AlertDialog.Builder(ctx);
            builder.setTitle("选择启用音效的书籍");
            builder.setMultiChoiceItems(bookNames, checked, new android.content.DialogInterface.OnMultiChoiceClickListener({
              onClick: function(dialog, which, isChecked) { checked[which] = isChecked; }
            }));
            builder.setPositiveButton("保存", new android.content.DialogInterface.OnClickListener({
              onClick: function(dialog, which) {
                var selected = [];
                for (var k = 0; k < checked.length; k++) if (checked[k]) selected.push(bookNames[k]);
                saveEnabledBooks(selected);
                showToast("已保存 " + selected.length + " 本书籍");
              }
            }));
            builder.setNegativeButton("取消", null);
            builder.setNeutralButton(selectAll ? "全不选" : "全选", new android.content.DialogInterface.OnClickListener({
              onClick: function(dialog, which) { showBookSelectionDialog(ctx, !selectAll); }
            }));
            builder.show();
          }
        }));
      } catch(e) {
        safeLog("获取书籍异常: " + e.message);
        showToast("获取书籍失败: " + e.message);
      }
    }
  }));
  thread.start();
}

